pub fn largest_power_of_two_le(n: i8) -> i8 {
    // Assumption: n >= 1
    // Find largest power of two z such that 1 <= z <= n and 2*z > n.
    let mut z: i8 = 1;

    // Keep doubling while the next power of two stays within [1, n].
    // Use i16 to avoid overflow when computing 2*z.
    while (z as i16) * 2 <= n as i16 {
        z = ((z as i16) * 2) as i8;
    }

    z
}

